```python
import os
import pickle
from torch.utils.data import Dataset, DataLoader
from tqdm import tqdm

class BRUSHDataset(Dataset):
    def __init__(self, root_dir):
        self.root_dir = root_dir
        self.data = []

        for writer_id in tqdm(os.listdir(self.root_dir)):
            if os.path.isdir(os.path.join(self.root_dir, writer_id)):
                for drawing_id in tqdm(os.listdir(os.path.join(self.root_dir, writer_id))):
                    with open(os.path.join(self.root_dir, writer_id, drawing_id), 'rb') as f:
                        sentence, drawing, label = pickle.load(f)
                        self.data.append((sentence, drawing, label))

    def __len__(self):
        return len(self.data)

    def __getitem__(self, idx):
        sentence, drawing, label = self.data[idx]
        return sentence, drawing, label

# Usage example
dataset = BRUSHDataset("data/BRUSH")
dataloader = DataLoader(dataset, batch_size=32, shuffle=True)

for sentences, drawings, labels in dataloader:
    # do something with the batch of data
```
this class iterates through the dataset and loads each file in the given path. the tqdm library helps keep track of the loading progress, making it easier to see how much data has been loaded at any given time.

the dataloader class inherits from PyTorch's Dataset class, with the `__init__` method loading all the data from the specified `root_dir` directory and storing it in a list. the `__len__` method returns the length of the data list, and the `__getitem__` method returns a single example from the dataset.

